SELECT STU_NM, DEPT_CD, GPA
  FROM STUDENT
 ORDER BY 2 NULLS FIRST, GPA DESC NULLS LAST;

-- (가)
SELECT DISTINCT DEPT_CD FROM STUDENT ORDER BY STU_NM;

-- (나)
SELECT DEPT_CD, COUNT(*) FROM STUDENT GROUP BY DEPT_CD ORDER BY GPA;

-- (다)
SELECT STU_NM
  FROM (SELECT STU_NM, DEPT_CD FROM STUDENT)
 ORDER BY GPA;

-- (라)
SELECT STU_NM FROM STUDENT ORDER BY GPA DESC, DEPT_CD;

SELECT E.STU_NO, G.GRADE
  FROM ENROLL E, GRADE_RANGE G
 WHERE E.SCORE BETWEEN G.LO AND G.HI;

-- (가)
SELECT STU_NM FROM STUDENT
 WHERE DEPT_CD = (SELECT DEPT_CD FROM DEPT WHERE DEPT_NM = '물리학과');

-- (나)
SELECT STU_NM FROM STUDENT
 WHERE DEPT_CD = (SELECT DEPT_CD FROM DEPT WHERE COLLEGE = '공과대학');

-- (가)
SELECT COUNT(*) FROM (SELECT ROW_NUMBER() OVER (ORDER BY SCORE DESC) AS R FROM ENROLL) WHERE R <= 3;

-- (나)
SELECT COUNT(*) FROM (SELECT RANK()       OVER (ORDER BY SCORE DESC) AS R FROM ENROLL) WHERE R <= 3;

-- (다)
SELECT COUNT(*) FROM (SELECT DENSE_RANK() OVER (ORDER BY SCORE DESC) AS R FROM ENROLL) WHERE R <= 3;

SELECT COUNT(*)
  FROM STU_CODE
 WHERE REGEXP_LIKE(CODE, '^CS|EE$');

